"""Parsers for catalog.txt, movements.txt and orders.txt.

All validation uses explicit ASCII character classes and ``re.fullmatch``;
``str.isdigit``, bare ``int()``/``Decimal()`` on unchecked text and
``str.splitlines`` are deliberately avoided (they accept far too much).
"""

import datetime
import re
from decimal import Context, Decimal

from .errors import ParseError
from .model import Movement, Order, Product
from .shelves import find_negative

SKU_RE = re.compile(r"[A-Za-z]{2,4}-[0-9]{3}")
PRICE_RE = re.compile(r"[0-9]+(\.[0-9]{1,2})?")
UINT_RE = re.compile(r"[0-9]+")
QTY_RE = re.compile(r"[+-]?[0-9]+")
ORDER_ID_RE = re.compile(r"[Ss][Oo]-[0-9]+")
DATE_RE = re.compile(r"([0-9]{4})-([0-9]{2})-([0-9]{2})")
MOVEMENT_RE = re.compile(
    r"([^ \t]+)[ \t]+([^ \t]+)[ \t]+([^ \t]+)(?:[ \t]+(.*))?", re.DOTALL
)
TAXES = ("standard", "reduced", "zero")
CENT = Decimal("0.01")


def parse_date(text):
    """A real ``YYYY-MM-DD`` date, or None."""
    m = DATE_RE.fullmatch(text)
    if not m:
        return None
    try:
        return datetime.date(int(m.group(1)), int(m.group(2)), int(m.group(3)))
    except ValueError:
        return None


def significant_lines(text):
    """Yield (line number, line) for every line that is not blank or comment.

    One leading BOM is dropped; lines end at LF (a CR just before it is
    dropped too) and nowhere else.
    """
    if text.startswith("﻿"):
        text = text[1:]
    lines = text.split("\n")
    if lines and lines[-1] == "":
        lines.pop()
    for number, line in enumerate(lines, 1):
        if line.endswith("\r"):
            line = line[:-1]
        stripped = line.strip()
        if not stripped or stripped.startswith("#"):
            continue
        yield number, line


def _uint(text):
    try:
        return int(text)
    except ValueError:  # absurdly long digit strings
        return None


def parse_catalog(text):
    """Return ``{SKU: Product}`` in file order."""
    catalog = {}
    for number, line in significant_lines(text):
        fields = [f.strip() for f in line.split("|")]
        if len(fields) not in (4, 5):
            raise ParseError(
                number, "expected 4 or 5 fields separated by '|', found %d" % len(fields)
            )
        sku, name, price, reorder = fields[:4]
        if not SKU_RE.fullmatch(sku):
            raise ParseError(number, "bad SKU %r" % sku)
        sku = sku.upper()
        if sku in catalog:
            raise ParseError(number, "duplicate SKU %s" % sku)
        if not name:
            raise ParseError(number, "name is empty")
        if not PRICE_RE.fullmatch(price):
            raise ParseError(number, "bad price %r" % price)
        value = Decimal(price)
        if value < CENT:
            raise ParseError(number, "price %r is below 0.01" % price)
        if not UINT_RE.fullmatch(reorder):
            raise ParseError(number, "bad reorder level %r" % reorder)
        reorder_value = _uint(reorder)
        if reorder_value is None:
            raise ParseError(number, "bad reorder level (too large)")
        tax = "standard"
        if len(fields) == 5:
            tax = fields[4].lower()
            if tax not in TAXES:
                raise ParseError(number, "bad tax %r (standard, reduced or zero)" % fields[4])
        catalog[sku] = Product(
            sku, name, value.quantize(CENT, context=Context(prec=len(price) + 5)), reorder_value, tax
        )
    return catalog


def parse_movements(text, catalog):
    """Return the movements in file order; stock may never go below zero."""
    movements = []
    for number, line in significant_lines(text):
        m = MOVEMENT_RE.fullmatch(line.strip(" \t"))
        if not m:
            raise ParseError(number, "expected DATE SKU QUANTITY [NOTE]")
        date_text, sku_text, qty_text, note = m.groups()
        date = parse_date(date_text)
        if date is None:
            raise ParseError(number, "bad date %r" % date_text)
        if not SKU_RE.fullmatch(sku_text):
            raise ParseError(number, "bad SKU %r" % sku_text)
        sku = sku_text.upper()
        if sku not in catalog:
            raise ParseError(number, "SKU %s is not in the catalogue" % sku)
        if not QTY_RE.fullmatch(qty_text):
            raise ParseError(number, "bad quantity %r" % qty_text)
        quantity = _uint(qty_text)
        if quantity is None:
            raise ParseError(number, "bad quantity (too large)")
        if quantity == 0:
            raise ParseError(number, "quantity may not be zero")
        movements.append(Movement(date, sku, quantity, (note or "").strip(), number))
    bad = find_negative(movements)
    if bad is not None:
        raise ParseError(
            bad.line, "stock of %s would go below zero on %s" % (bad.sku, bad.date.isoformat())
        )
    return movements


def parse_orders(text, catalog):
    """Return the orders in file order."""
    orders = []
    seen = set()
    for number, line in significant_lines(text):
        fields = re.split(r"[ \t]+", line.strip(" \t"))
        if len(fields) != 4:
            raise ParseError(
                number, "expected ORDER DATE CUSTOMER LINES, found %d fields" % len(fields)
            )
        order_id, date_text, customer, lines_text = fields
        if not ORDER_ID_RE.fullmatch(order_id):
            raise ParseError(number, "bad order number %r" % order_id)
        order_id = order_id.upper()
        if order_id in seen:
            raise ParseError(number, "duplicate order %s" % order_id)
        date = parse_date(date_text)
        if date is None:
            raise ParseError(number, "bad date %r" % date_text)
        lines = []
        skus = set()
        for piece in lines_text.split(","):
            sku, star, qty = piece.partition("*")
            if not star or not SKU_RE.fullmatch(sku):
                raise ParseError(number, "bad order line %r (expected SKU*QUANTITY)" % piece)
            sku = sku.upper()
            if sku not in catalog:
                raise ParseError(number, "SKU %s is not in the catalogue" % sku)
            if sku in skus:
                raise ParseError(number, "SKU %s appears twice in the order" % sku)
            if not UINT_RE.fullmatch(qty):
                raise ParseError(number, "bad quantity %r" % qty)
            quantity = _uint(qty)
            if quantity is None or quantity < 1:
                raise ParseError(number, "quantity must be 1 or more, got %r" % qty)
            skus.add(sku)
            lines.append((sku, quantity))
        seen.add(order_id)
        orders.append(Order(order_id, date, customer, lines, number))
    return orders
"""The orders: pricing, shipped-so-far, fulfil planning, invoices, report."""

from decimal import ROUND_HALF_UP, Context, Decimal, localcontext

from .errors import Refusal
from .model import Order, Quote, QuoteLine
from .shelves import count_order

CENT = Decimal("0.01")
ZERO = Decimal("0.00")
RATES = {"standard": Decimal("0.20"), "reduced": Decimal("0.05"), "zero": Decimal("0")}
THRESHOLD = Decimal("500.00")


def _round(value):
    return value.quantize(CENT, rounding=ROUND_HALF_UP)


def _neg(value):
    """Negate, never producing -0.00."""
    return ZERO if value == 0 else -value


def _pennies(value):
    return int(value.scaleb(2))


def price_order(order, catalog):
    """Price a whole order; returns a Quote (see the package docs)."""
    digits = sum(len(str(q)) for _, q in order.lines)
    with localcontext(Context(prec=60 + 2 * digits)):
        lines = []
        for sku, quantity in order.lines:
            unit = catalog[sku].price
            gross = _round(quantity * unit)
            if quantity >= 50:
                discount = _neg(_round(gross * Decimal("0.10")))
            elif quantity >= 10:
                discount = _neg(_round(gross * Decimal("0.05")))
            else:
                discount = ZERO
            lines.append(QuoteLine(sku, quantity, unit, gross, discount, gross + discount))
        subtotal = sum((l.net for l in lines), ZERO)
        if subtotal >= THRESHOLD:
            order_discount = _neg(_round(subtotal * Decimal("0.03")))
        else:
            order_discount = ZERO

        # Share the order discount over the lines, to the penny.
        shares = [0] * len(lines)
        if order_discount != 0:
            total_p = _pennies(abs(order_discount))
            sub_p = _pennies(subtotal)
            shares = [total_p * _pennies(l.net) // sub_p for l in lines]
            remainders = [total_p * _pennies(l.net) % sub_p for l in lines]
            left = total_p - sum(shares)
            ranked = sorted(range(len(lines)), key=lambda i: (-remainders[i], i))
            for i in ranked[:left]:
                shares[i] += 1

        tax = ZERO
        for line, share in zip(lines, shares):
            taxable = line.net - Decimal(share).scaleb(-2)
            tax += _round(taxable * RATES[catalog[line.sku].tax])
        tax = _round(tax)
        total = _round(subtotal + order_discount + tax)
        return Quote(lines, _round(subtotal), order_discount, tax, total)


def order_note(order_id):
    return "order " + order_id


def shipped_so_far(order, movements):
    """Units already shipped for each order line (capped at the ordered qty)."""
    note = order_note(order.id)
    sent = {}
    for m in movements:
        if m.quantity < 0 and m.note == note:
            sent[m.sku] = sent.get(m.sku, 0) - m.quantity
    return [min(sent.get(sku, 0), qty) for sku, qty in order.lines]


def order_status(order, shipped):
    if all(s >= q for (_, q), s in zip(order.lines, shipped)):
        return "complete"
    if not any(shipped):
        return "open"
    return "partial"


def available(sku, movements, date):
    """How many units of SKU may be shipped on DATE without any later
    movement taking the stock below zero."""
    balance = 0
    lowest = None
    for m in count_order(movements):
        if m.sku != sku:
            continue
        balance += m.quantity
        if m.date > date:
            lowest = balance if lowest is None else min(lowest, balance)
    on_date = sum(m.quantity for m in movements if m.sku == sku and m.date <= date)
    best = on_date if lowest is None else min(on_date, lowest)
    return max(0, best)


def plan_fulfil(order, movements, date):
    """For each order line: (sku, shipping now, still owed afterwards)."""
    if date < order.date:
        raise Refusal(
            "%s is dated %s; cannot fulfil on %s"
            % (order.id, order.date.isoformat(), date.isoformat())
        )
    shipped = shipped_so_far(order, movements)
    plan = []
    for (sku, qty), done in zip(order.lines, shipped):
        owed = qty - done
        ship = min(owed, available(sku, movements, date))
        plan.append((sku, ship, owed - ship))
    return plan


def invoice_order(order, movements):
    """The order restricted to what has shipped, or None when nothing has."""
    shipped = shipped_so_far(order, movements)
    lines = [(sku, s) for (sku, _), s in zip(order.lines, shipped) if s > 0]
    if not lines:
        return None
    return Order(order.id, order.date, order.customer, lines, order.line)


def _id_key(order_id):
    digits = order_id[3:].lstrip("0")
    return (len(digits), digits)


def report_rows(orders, catalog, movements):
    """One dict per order, by order date, order number, then id."""
    rows = []
    for order in sorted(orders, key=lambda o: (o.date, _id_key(o.id), o.id)):
        shipped = shipped_so_far(order, movements)
        invoice = invoice_order(order, movements)
        invoiced = price_order(invoice, catalog).total if invoice else ZERO
        rows.append(
            {
                "order": order.id,
                "date": order.date.isoformat(),
                "customer": order.customer,
                "status": order_status(order, shipped),
                "ordered": sum(q for _, q in order.lines),
                "shipped": sum(shipped),
                "quoted": price_order(order, catalog).total,
                "invoiced": invoiced,
            }
        )
    return rows
"""The shelves: stock levels, status, low list, history, safe appends."""

from .errors import Refusal
from .model import Movement


def count_order(movements):
    """Movements in the order they count: by date, file order within a day."""
    return sorted(movements, key=lambda m: m.date)


def find_negative(movements):
    """Return the first movement (in count order) that takes any product
    below zero, or None."""
    balance = {}
    for m in count_order(movements):
        total = balance.get(m.sku, 0) + m.quantity
        balance[m.sku] = total
        if total < 0:
            return m
    return None


def stock_levels(catalog, movements):
    """SKU -> quantity on the shelf, for every product in the catalogue."""
    levels = {sku: 0 for sku in catalog}
    for m in movements:
        levels[m.sku] = levels.get(m.sku, 0) + m.quantity
    return levels


def status(onhand, reorder):
    if onhand == 0:
        return "out"
    if onhand <= reorder:
        return "low"
    return "ok"


def stock_rows(catalog, movements):
    """(product, onhand, status) for every product, by SKU."""
    levels = stock_levels(catalog, movements)
    rows = []
    for sku in sorted(catalog):
        product = catalog[sku]
        rows.append((product, levels[sku], status(levels[sku], product.reorder)))
    return rows


def low_rows(catalog, movements):
    """(product, onhand, buy) for every product that is low or out, by SKU."""
    rows = []
    for product, onhand, st in stock_rows(catalog, movements):
        if st != "ok":
            rows.append((product, onhand, max(1, 2 * product.reorder - onhand)))
    return rows


def history_rows(sku, movements):
    """(movement, balance after it) for one SKU, in count order."""
    balance = 0
    rows = []
    for m in count_order(movements):
        if m.sku == sku:
            balance += m.quantity
            rows.append((m, balance))
    return rows


def signed(quantity):
    return "%+d" % quantity


def format_movement(m):
    """``DATE SKU ±QUANTITY[ NOTE]`` as written to movements.txt."""
    text = "%s %s %s" % (m.date.isoformat(), m.sku, signed(m.quantity))
    if m.note:
        text += " " + m.note
    return text


def check_append(existing, new):
    """Refuse unless existing + new movements still never go below zero."""
    bad = find_negative(list(existing) + list(new))
    if bad is not None:
        raise Refusal(
            "stock of %s would go below zero on %s" % (bad.sku, bad.date.isoformat())
        )


def new_movement(date, sku, quantity, note):
    return Movement(date, sku, quantity, note)
"""Plain data classes returned by the library."""

import datetime
from dataclasses import dataclass, field
from decimal import Decimal
from typing import List, Tuple


@dataclass
class Product:
    sku: str
    name: str
    price: Decimal
    reorder: int
    tax: str = "standard"


@dataclass
class Movement:
    date: datetime.date
    sku: str
    quantity: int
    note: str = ""
    # Line number in movements.txt (0 when built by hand); not part of equality.
    line: int = field(default=0, compare=False, repr=False)


@dataclass
class Order:
    id: str
    date: datetime.date
    customer: str
    lines: List[Tuple[str, int]]
    line: int = field(default=0, compare=False, repr=False)


@dataclass
class QuoteLine:
    sku: str
    quantity: int
    unit: Decimal
    gross: Decimal
    discount: Decimal
    net: Decimal


@dataclass
class Quote:
    lines: List[QuoteLine]
    subtotal: Decimal
    order_discount: Decimal
    tax: Decimal
    total: Decimal
"""Exceptions shared by the whole package."""


class ParseError(ValueError):
    """A mistake in one line of a data file.

    ``line`` is the line number (counting from 1, blank and comment lines
    included); the message always starts with ``line N: ``.
    """

    def __init__(self, line, reason):
        super().__init__("line %d: %s" % (line, reason))
        self.line = line
        self.reason = reason


class Refusal(Exception):
    """A request that is understood but refused (unknown SKU, stock would go
    below zero, nothing shipped yet, ...)."""
# Stockroom

I run a small online shop out of a spare room and I keep everything in plain text files: what I sell,
what came in and went out of the shelves, and what customers ordered. I'd like a Python tool called
**stockroom** that reads those files and answers three questions: what is on the shelves and what
needs buying, what an order costs, and what I can ship today. It should work two ways: as a library I
can `import stockroom` from my own scripts, and as a `stockroom` command in the terminal. Python 3.9 or
newer, standard library only (no third-party packages). Running `pip install .` in the project folder
should give me both the importable library and the `stockroom` command.

There are two halves to it: the **shelves** (the catalogue, the stock movements, what is low) and the
**orders** (prices, discounts, tax, shipping what is in stock, invoices, a report). The orders half
depends on the shelves, so build them in that order.

## The three files

They live in one folder (the command's current folder, or the one named by `--dir`). Text is UTF-8; a
byte order mark at the start of a file is ignored; a line ends at LF or at CRLF and nowhere else.
In every file, blank lines are ignored, and so are lines starting with `#` (after any leading
whitespace). Anything else that does not follow the rules below is a mistake in my file, and the tool
must tell me which file and which line (counting from 1, blank and comment lines included).

### `catalog.txt` — what I sell

One product per line, fields separated by `|`, whitespace around each field trimmed:

```
# SKU   | name            | price | reorder | tax
AB-100 | Garden gnome     | 12.50 | 5       | standard
cd-205 | Seed packet, mix | 1.99  | 40      | reduced
EF-310 | Gift voucher     | 25.00 | 0
```

- **SKU**: two to four letters, a dash, three digits (`AB-100`). Letters in any case are accepted; the
  SKU is always shown in upper case. Two lines with the same SKU are a mistake.
- **name**: not empty. It may contain anything except `|`.
- **price**: in pounds, at least `0.01`, at most two decimal places (`12`, `12.5`, `1.99` are fine;
  `12.505`, `1,000.00`, `-3` and `abc` are not).
- **reorder**: the stock level at or under which I need to buy more: a whole number, zero or more.
- **tax** (optional, `standard` when the field is left out, so a line has four or five fields): one of
  `standard` (20 %), `reduced` (5 %) or `zero` (0 %), in any case.

### `movements.txt` — what came in and went out

One movement per line: `DATE SKU QUANTITY [NOTE]`, separated by any amount of spaces or tabs. The note
is the rest of the line exactly as written, apart from trimming whitespace at both ends.

```
2024-03-01 AB-100 +20 first delivery
2024-03-04 ab-100 -3 order SO-1001
2024-03-05 CD-205 40
```

- **DATE** is `YYYY-MM-DD` and a date that exists (`2024-02-30` is a mistake).
- **SKU** must be in the catalogue (any case).
- **QUANTITY** is a whole number that is not zero, with an optional sign: positive means stock in,
  negative means stock out.
- The movements count in date order; movements on the same day keep the order of the file. The
  stock of a product may never be below zero at any point in that order. The line that takes it below
  zero is the mistake.

### `orders.txt` — what customers ordered

One order per line: `ORDER DATE CUSTOMER LINES`, separated by any amount of spaces or tabs:

```
SO-1001 2024-03-03 acme AB-100*12,CD-205*3
SO-1002 2024-03-09 Bea ab-100*2
```

- **ORDER** is `SO-` (any case) and one or more digits, shown in upper case; `SO-7` and `SO-007` are two
  different orders. It is unique: a second line with the same order number is a mistake.
- **DATE** as above. **CUSTOMER** is one word, shown as typed.
- **LINES** is one or more `SKU*QUANTITY` pairs separated by commas, no spaces. The SKU must be in the
  catalogue and appear once per order; the quantity is a whole number of one or more (no sign).

A missing `catalog.txt` is an error for every command. A missing `movements.txt` or `orders.txt` is
just empty. A command reads only the files it needs, and a mistake in a file it does not read is not its
business: the shelves commands (`stock`, `low`, `history`, `receive`, `ship`) read the catalogue and the
movements; `quote` reads the catalogue and the orders; `fulfil`, `invoice` and `report` read all three.

## Using it as a library

```python
import stockroom

catalog = stockroom.parse_catalog(open("catalog.txt").read())
moves = stockroom.parse_movements(open("movements.txt").read(), catalog)
print(stockroom.stock_levels(catalog, moves))
```

- `parse_catalog(text)` returns a `dict` of SKU to a product. A product has `.sku`, `.name`, `.price`
  (a `decimal.Decimal`), `.reorder` (an `int`) and `.tax` (`"standard"`, `"reduced"` or `"zero"`).
- `parse_movements(text, catalog)` returns a list of movements in the order they appear in the text,
  each with `.date` (a `datetime.date`), `.sku`, `.quantity` (an `int`) and `.note` (a `str`, empty when
  there is none).
- `parse_orders(text, catalog)` returns a list of orders in the order they appear, each with `.id`,
  `.date`, `.customer` and `.lines`: a list of `(sku, quantity)` pairs in the order written.
- A bad line makes any of these raise `stockroom.ParseError`. It is a `ValueError`, its `.line`
  attribute is the line number, and its message mentions `line N`.
- `stock_levels(catalog, movements)` is a `dict` of SKU to the quantity on the shelf, for every product
  in the catalogue (zero when it never moved).
- `price_order(order, catalog)` prices a whole order as described under *Prices* and returns a quote with
  `.lines` (each with `.sku`, `.quantity`, `.unit`, `.gross`, `.discount`, `.net`), `.subtotal`,
  `.order_discount`, `.tax` and `.total`, all `Decimal`s with two decimal places. A discount is zero or
  negative.

## Prices

All of this is exact to the penny and every rounding step rounds halves **up** (`0.005` becomes `0.01`).

1. A line's **gross** is its quantity times the unit price.
2. A line gets a **volume discount** of 5 % of its gross when the quantity is 10 or more, and 10 % when it
   is 50 or more (not both), rounded to the penny. The line's **net** is gross minus that.
3. The **subtotal** is the sum of the nets. When it is £500.00 or more the whole order gets an **order
   discount** of 3 % of the subtotal, rounded to the penny.
4. The order discount is shared out over the lines in proportion to their nets, to the penny: each line's
   share is rounded down, and the pennies left over go one each to the lines with the biggest part of a
   penny lost (the earlier line first on a tie). A line's **taxable amount** is its net less its share.
5. **Tax** is worked out per line on its taxable amount at its product's rate, rounded to the penny, and
   added up. Prices do not include tax.
6. The **total** is the subtotal, plus the order discount (a negative number), plus the tax.

## Using it from the terminal

Every command takes `--dir DIR` anywhere on the line (default: the current folder). Options are spelled out in full.

```
$ stockroom stock
AB-100 17 ok Garden gnome
CD-205 40 low Seed packet, mix
EF-310 0 out Gift voucher

$ stockroom quote SO-1001
SO-1001 2024-03-03 acme
AB-100 12 12.50 150.00 -7.50 142.50
CD-205 3 1.99 5.97 0.00 5.97
subtotal 148.47
order discount 0.00
tax 28.80
total 177.27
```

**The shelves**

- `stockroom stock [--json]` prints one line per product, by SKU: `SKU ONHAND STATUS NAME` separated by single
  spaces. The status is `out` when the stock is zero, `low` when it is above zero and at or under the product's
  reorder level, `ok` otherwise.
- `stockroom low [--json]` prints one line for each product that is `low` or `out`, by SKU:
  `SKU ONHAND REORDER BUY` where BUY is how many to buy to get back to twice the reorder level, and at least 1
# .rtdd/config.yaml — written by `rtdd init`. Every list is globs over
# repo-relative paths; a key you set replaces its default wholesale.
# See docs/specs/2026-10-07-node-graph.md §4.1, §5 and §6.

# Files the scanner never reads.
scan_exclude:
  - "vendor/**"
  - "node_modules/**"
  - "third_party/**"
  - "**/*.min.js"
  - "dist/**"
  - "build/**"
  - ".rtdd/**"
  - "graphify-out/**"

# Files read for their file node and the paths they name, never for definitions.
definition_exclude:
  - "**/*.md"
  - "**/*.mdc"
  - "**/*.markdown"
  - "**/*.rst"
  - "**/*.txt"
  - "**/*.adoc"

# A function, method or test in a matching file is a test.
test_files:
  - "**/test_*"
  - "**/*_test.*"
  - "**/*.test.*"
  - "**/*.spec.*"
  - "**/*Test.*"
  - "**/*Tests.*"
  - "**/tests/**"
  - "**/test/**"
  - "**/spec/**"
  - "**/__tests__/**"

# A matching file is never a test file, whatever test_files says.
test_exclude:
  - "**/testdata/**"
  - "**/fixtures/**"

# A matching test file runs only as a whole: its functions are helpers, its path is the test.
whole_file_tests:
  - "**/test_*.sh"
  - "**/*_test.sh"
  - "**/*.bats"

# graphify's graph, used when this file exists. rtdd never runs graphify.
graphify_path: "graphify-out/graph.json"

# graphify is ignored when more than this share of its code files is stale.
max_stale_ratio: 0.5

